def _normalize_key(label):
    lowered = label.lower()
    result = []
    prev_underscore = False
    for ch in lowered:
        if ch.isalnum():
            result.append(ch)
            prev_underscore = False
        else:
            if not prev_underscore:
                result.append('_')
                prev_underscore = True
    normalized = ''.join(result).strip('_')
    return 'kx7-' + normalized

