_PREFIX = "kx7-"


def _normalize_key(label):
    text = str(label).lower()
    chars = []
    last_was_sep = True

    for ch in text:
        if ch.isalnum():
            chars.append(ch)
            last_was_sep = False
        elif not last_was_sep:
            chars.append("_")
            last_was_sep = True

    if chars and chars[-1] == "_":
        chars.pop()

    return _PREFIX + "".join(chars)


def store(k, v, secs):
    return cache.put(_normalize_key(k), v, ttl=secs)

